// A single presentation pass for historical HTML and articles generated by the CMS.
function element(source,className){
 const tags=/<([a-z][\w-]*)\b([^>]*)>/gi;let match;
 while((match=tags.exec(source))){
  const classes=/\bclass="([^"]*)"/.exec(match[2])?.[1].split(/\s+/)||[];
  if(!classes.includes(className))continue;
  const start=match.index,openEnd=tags.lastIndex,tag=match[1];
  const pairs=new RegExp('<(/?)'+tag+'\\b[^>]*>','gi');pairs.lastIndex=openEnd;
  let depth=1,next;
  while((next=pairs.exec(source))){depth+=next[1]?-1:1;if(depth===0)return {start,end:pairs.lastIndex,inner:source.slice(openEnd,next.index),html:source.slice(start,pairs.lastIndex)};}
 }
 return null;
}
export function enforceGuidePresentation(source){
 let html=String(source);
 html=html.replace(/<body\b([^>]*)>/i,(tag,attrs)=>/\bclass="/.test(attrs)?tag.replace(/class="([^"]*)"/,(_,classes)=>'class="'+[...new Set([...classes.split(/\s+/),'cr-magazine'])].join(' ')+'"'):'<body'+attrs+' class="cr-magazine">');
 html=html.replace(/class="([^"]*)"/g,(_,value)=>'class="'+value.split(/\s+/).map(c=>({'reading-layout':'bf-story-layout','reading-copy':'bf-story-body','article-hero':'bf-story-hero'}[c]||c)).join(' ')+'"');
 html=html.replace(/<strong>Perché lo proponiamo:?<\/strong>\s*/g,'').replace(/\s*·\s*\d+ MIN DI LETTURA/g,'');
 html=html.replace(/<section\b([^>]*\bclass="[^"]*\bbf-pick\b[^"]*"[^>]*)>([\s\S]*?)<\/section>/g,(whole,attrs,body)=>{
  if(/\bcr-magazine-pick\b/.test(attrs))return whole;
  const index=element(body,'bf-pick-index'),content=element(body,'bf-pick-content'),media=element(body,'bf-pick-media'),retail=element(body,'bf-pick-retail');
  if(!index||!content)return whole;
  const heading=content.inner.match(/<h[23]\b[^>]*>[\s\S]*?<\/h[23]>/)?.[0];if(!heading)return whole;
  const description=content.inner.replace(heading,'');
  const updated=attrs.replace(/class="([^"]*)"/,(_,classes)=>'class="'+classes+' cr-magazine-pick"');
  return '<section'+updated+'><div class="cr-pick-heading">'+index.html+heading+'</div>'+(media?.html||'')+'<div class="bf-pick-content">'+description+'</div>'+(retail?'<div class="bf-pick-shop">'+retail.html+'</div>':'')+'</section>';
 });
 // One concise note, instead of a large empty box for every unavailable photo.
 html=html.replace(/(<(?:div|section)\b[^>]*class="[^"]*\bcr-exact-products\b[^"]*"[^>]*>)/g,(tag,_,offset)=>{
  if(html.slice(offset+tag.length,offset+tag.length+150).includes('cr-guide-media-note'))return tag;
  return tag+'<p class="cr-guide-media-note" role="status">Le foto dei prodotti non sono disponibili al momento. Puoi comunque leggere le idee e i consigli qui sotto.</p>';
 });
 if(!html.includes('assets/guide-editorial.css'))html=html.replace('</head>','<link rel="stylesheet" href="/assets/guide-editorial.css"></head>');
 return html;
}
